<script setup lang="ts">import { useSettingsStore } from '../stores/settings'; const settings=useSettingsStore(); const roles=['Narrator','Speaker 1','Speaker 2','Speaker 3'] as const</script>
<template><div class="page narrow"><p class="eyebrow">Listening setup</p><h1>Voice settings</h1><p class="lead">Available voices come from your browser and operating system. Select a distinct English voice for each role where possible.</p><div class="settings-card"><label v-for="role in roles" :key="role"><span>{{ role }} voice</span><select v-model="settings.selection[role]"><option value="">Browser default</option><option v-for="voice in settings.voices" :key="voice.voiceURI" :value="voice.voiceURI">{{ voice.name }} — {{ voice.lang }}</option></select></label><label><span>Speech rate: {{ settings.rate.toFixed(1) }}</span><input v-model.number="settings.rate" type="range" min="0.8" max="1.2" step="0.1"/></label><button type="button" @click="settings.refresh">Refresh available voices</button><p class="microcopy">Voice choices and speech rate are saved in LocalStorage. Exam mode uses rate 1.0 by default in the content flow; Practice mode honors this setting.</p></div></div></template>
